,[1041453]={["id"]=1041453,["key"]=1041453,["nextId"]={1041454}
,["talk"]="鳴刃",["header_center"]=1,["talk_en"]="Buzzing Blade",["showStory"]=2,["content"]="她們該不會也對那些板塊的人做了——",["talkRoleID"]={7041001}
