,[2200238]={["key"]=2200238,["id"]=2200238,["nextId"]={2200239}
,["content"]="從希恩的房間到各處實驗室的路上，需要經過一個只有成人頭部大小的視窗。從視窗往外看，能看到的只是一小片狹窄的天空以及覆蓋著水泥的地面，風景乏味到驚人。",["showStory"]=1}
,[2200240]={["roleInfos"]={{["id"]=9909003,["out"]=2,["pos"]=2}
}
,["imgChangeType"]=1,["imgContent"]={"Bg_9154.jpg"}
