,["talk"]="涅毒",["talkRoleID"]={5028001}
,["talk_en"]="Venomous",["showStory"]=2,["content"]="……",["header_center"]=4}
,[1042051]={["id"]=1042051,["key"]=1042051,["nextId"]={1042052}
,["talk"]="涅毒",["header_center"]=1,["talk_en"]="Venomous",["showStory"]=2,["content"]="那麼，那個白色衣服的人是誰？",["talkRoleID"]={5028001}
