,[1042113]={["id"]=1042113,["key"]=1042113,["nextId"]={1042114}
,["talk"]="鳴刃",["header_center"]=2,["talk_en"]="Buzzing Blade",["showStory"]=2,["content"]="還有那些住民們說的，對直接感染者的處置……",["talkRoleID"]={7041001}
