,["talk_en"]="hoody",["showStory"]=2,["content"]="刃、刃齒……",["header_center"]=1}
,[2020559]={["roleInfos"]={{["id"]=3018001,["enter"]=2,["pos"]=2}
}
,["id"]=2020559,["key"]=2020559,["nextId"]={2020560}
,["talk"]="刃齒",["talkRoleID"]={3018001}
,["talk_en"]="Machairodus",["showStory"]=2,["content"]="見到老朋友不該高興一下嗎？懷特。",["header_center"]=2}
,[2020560]={["roleInfos"]={{["id"]=9939001,["enter"]=2,["pos"]=2}
}
