,[1011624]={["roleInfos"]={{["id"]=7007001,["enter"]=2,["pos"]=2}
}
,["id"]=1011624,["key"]=1011624,["nextId"]={1011625}
,["talk"]="雅典娜",["talkRoleID"]={7007001}
,["talk_en"]="Athena",["showStory"]=2,["content"]="或許是NOVA輻射的改變，或者是我們碎星人核心的特性，具體原理難以確認。",["header_center"]=5}
