,["id"]=1012270,["nextId"]={1012271}
,["talk"]="赤狼",["talkRoleID"]={3020001}
,["talk_en"]="Direwolf",["key"]=1012270,["content"]="剛剛轉移的時候好像意識都混在一起了，我似乎看見了龍弦隊長。",["showStory"]=2}
,[2090060]={["isLeader"]=1,["id"]=2090060,["key"]=2090060,["nextId"]={2090061}
,["talk"]="%s",["showIcon"]=1,["showStory"]=2,["talkRoleID"]={100000}
,["content"]="發現你們以為的事情一件都沒有實現？",["header_center"]=6}
