}
,["id"]=1012413,["key"]=1012413,["nextId"]={1012414}
,["talk"]="哈迪斯",["talkRoleID"]={7005004}
,["talk_en"]="Hades",["showStory"]=2,["content"]="她即使看的見，現在也只知道等待著“有趣的獵物”靠近。",["header_center"]=2}
,[2090346]={["roleInfos"]={{["id"]=7045001,["enter"]=2,["pos"]=2}
