,[2091103]={["id"]=2091103,["key"]=2091103,["nextId"]={2091104}
,["talk"]="夜暝",["header_center"]=1,["talk_en"]="Midnight",["showStory"]=2,["content"]="但這些事情所指向的目標，到底是什麼？",["talkRoleID"]={7045001}
