,["id"]=1013242,["nextId"]={1013243}
,["talk"]="赤狼",["talkRoleID"]={3020001}
,["talk_en"]="Direwolf",["key"]=1013242,["content"]="沒問題，至少進去的路我會替你們守住。",["showStory"]=2}
