,{["interval"]=50,["type"]=3,["time"]=0.5,["force"]={200,200}
}
}
,["roleInfos"]={{["id"]=7002001,["out"]=2,["pos"]=2}
}
,["nextId"]={1013647}
,["id"]=1013646,["effSoundInfos"]={{["key"]="amb_lighting"}
}
,["content"]="迎擊的響雷直接劈中兩台造物。",["showStory"]=1}
,[1013647]={["key"]=1013647,["id"]=1013647,["nextId"]={1013648}
,["content"]="如機能癱瘓似的，兩機墜進雲層，不見了蹤影。",["showStory"]=1}
,[1013648]={["roleInfos"]={{["id"]=7002001,["enter"]=2,["pos"]=2}
}
,["id"]=1013648,["nextId"]={1013649}
,["talk"]="宙斯",["talkRoleID"]={7002001}
,["talk_en"]="Zeus",["key"]=1013648,["content"]="你的把戲不過如此。",["showStory"]=2}
,[1013649]={["roleInfos"]={{["id"]=7005004,["enter"]=2,["pos"]=2}
}
,["id"]=1013649,["key"]=1013649,["nextId"]={1013650}
,["talk"]="哈迪斯",["talkRoleID"]={7005004}
,["talk_en"]="Hades",["showStory"]=2,["content"]="在你看來是這樣嗎？",["header_center"]=2}
,[1013650]={["id"]=1013650,["key"]=1013650,["nextId"]={1013651}
,["talk"]="哈迪斯",["header_center"]=2,["talk_en"]="Hades",["showStory"]=2,["content"]="我得謝謝你替我省了給它們充能的功夫。",["talkRoleID"]={7005004}
