,["talk"]="宙斯",["talkRoleID"]={7002001}
,["talk_en"]="Zeus",["key"]=1013659,["content"]="這兩台造物就是你的底牌嗎？",["showStory"]=2}
,[1013660]={["roleInfos"]={{["id"]=7005001,["enter"]=2,["pos"]=2}
}
