,["id"]=1013669,["key"]=1013669,["nextId"]={1013670}
,["talk"]="哈迪斯",["talkRoleID"]={7005001}
,["talk_en"]="Hades",["showStory"]=2,["content"]="那就沒什麼好說的了。塔納托斯，修普諾斯——",["header_center"]=1}
,[1013670]={["id"]=1013670,["key"]=1013670,["nextId"]={-1}
,["talk"]="哈迪斯",["header_center"]=1,["talk_en"]="Hades",["showStory"]=2,["content"]="給我撕碎她。",["talkRoleID"]={7005001}
}
