,[1013706]={["key"]=1013706,["id"]=1013706,["nextId"]={1013707}
,["content"]="儘管已全力閃躲，但光束組成的包圍網根本沒有絕處逢生的空隙，除了正面承受，沒有任何辦法。",["showStory"]=1}
,[1013707]={["roleInfos"]={{["id"]=7002001,["enter"]=2,["pos"]=2}
}
,["id"]=1013707,["key"]=1013707,["nextId"]={1013708}
,["talk"]="宙斯",["talkRoleID"]={7002001}
,["talk_en"]="Zeus",["showStory"]=2,["content"]="嗚……",["header_center"]=6}
