,[1013711]={["key"]=1013711,["header_center"]=2,["id"]=1013711,["nextId"]={1013712}
,["content"]="展現出的默契和戰術，都是循規蹈矩的造物絕對無法重現出來的。",["showStory"]=1}
,[1013712]={["id"]=1013712,["key"]=1013712,["nextId"]={1013713}
,["talk"]="哈迪斯",["header_center"]=2,["talk_en"]="Hades",["showStory"]=2,["content"]="你是否覺得我很卑鄙？",["talkRoleID"]={7005004}
