}
,["id"]=1013716,["key"]=1013716,["nextId"]={1013717}
,["talk"]="宙斯",["talkRoleID"]={7002001}
,["talk_en"]="Zeus",["showStory"]=2,["content"]="想都別想。",["header_center"]=1}
