,["showStory"]=2,["header_right"]=4,["talkRoleID"]={7002001}
,["talk_en"]="Zeus",["nextId"]={1013773}
,["header_left"]=2,["content"]="我要感謝你，是你讓我找到了自我。",["talk"]="宙斯"}
,[1013773]={["roleInfos"]={{["id"]=7005004,["enter"]=2,["pos"]=2}
}
,["key"]=1013773,["id"]=1013773,["mask"]={1,0,1}
,["showStory"]=2,["header_right"]=1,["talkRoleID"]={7005004}
,["talk_en"]="Hades",["nextId"]={1013774}
,["header_left"]=2,["content"]="少說廢話，要動手就快動手。",["talk"]="哈迪斯"}
,[1013774]={["roleInfos"]={{["id"]=7002001,["enter"]=2,["pos"]=2}
}
,["key"]=1013774,["id"]=1013774,["mask"]={1,0,1}
,["nextId"]={1013775}
,["header_right"]=1,["talkRoleID"]={7002001}
,["talk_en"]="Zeus",["showStory"]=2,["content"]="那就如你所願。",["talk"]="宙斯"}
,[1013775]={["key"]=1013775,["roleInfos"]={{["id"]=7002001,["out"]=2,["pos"]=2}
}
,["nextId"]={1013776}
,["id"]=1013775,["header_left"]=1,["content"]="填滿視野的蒼藍火球開始膨脹，灼眼的光芒眼看就要將哈迪斯湮沒。",["showStory"]=1}
,[1013776]={["roleInfos"]={{["id"]=1001001,["enter"]=2,["pos"]=2}
}
