,["talk"]="阿爾卑斯",["talkRoleID"]={1001001}
,["talk_en"]="Alps",["showStory"]=2,["content"]="休想得逞。",["header_center"]=1}
,[1013777]={["roleInfos"]={{["id"]=7002001,["enter"]=2,["pos"]=2}
}
,["id"]=1013777,["nextId"]={1013778}
,["talk"]="宙斯",["talkRoleID"]={7002001}
,["talk_en"]="Zeus",["key"]=1013777,["content"]="地球人嗎？",["showStory"]=2}
,[1013778]={["talk"]="宙斯",["key"]=1013778,["talkRoleID"]={7002001}
,["talk_en"]="Zeus",["id"]=1013778,["nextId"]={1013779}
,["content"]="區區低階文明的生命竟能來到這。",["showStory"]=2}
,[1013779]={["roleInfos"]={{["id"]=1001001,["enter"]=2,["pos"]=2}
}
,["id"]=1013779,["key"]=1013779,["nextId"]={1013780}
,["talk"]="阿爾卑斯",["talkRoleID"]={1001001}
,["talk_en"]="Alps",["showStory"]=2,["content"]="你的自大會讓你付出沉重的代價。",["header_center"]=1}
,[1013780]={["roleInfos"]={{["id"]=7002001,["enter"]=2,["pos"]=2}
}
,["id"]=1013780,["nextId"]={1013781}
,["talk"]="宙斯",["talkRoleID"]={7002001}
,["talk_en"]="Zeus",["key"]=1013780,["content"]="至少讓我稱讚下你的毅力吧。",["showStory"]=2}
