,["talk"]="哈迪斯",["talkRoleID"]={7005004}
,["talk_en"]="Hades",["showStory"]=2,["content"]="難得見你說些像樣的話。",["header_center"]=2}
,[1014218]={["roleInfos"]={{["id"]=7001001,["enter"]=2,["pos"]=2}
}
,["id"]=1014218,["key"]=1014218,["nextId"]={1014219}
,["talk"]="宙斯",["talkRoleID"]={7001001}
,["talk_en"]="Zeus",["showStory"]=2,["content"]="彼此。",["header_center"]=2}
