,["talk"]="哈迪斯",["talkRoleID"]={7005004}
,["talk_en"]="Hades",["showStory"]=2,["content"]="這句話到底是在對誰說呢？",["header_center"]=2}
,[1014226]={["roleInfos"]={{["id"]=7001001,["enter"]=2,["pos"]=2}
}
