,["id"]=1014238,["key"]=1014238,["nextId"]={1014239}
,["talk"]="哈迪斯",["talkRoleID"]={7005004}
,["talk_en"]="Hades",["showStory"]=2,["content"]="那又怎麼樣？",["header_center"]=1}
,[1014239]={["roleInfos"]={{["id"]=7001001,["enter"]=2,["pos"]=2}
}
,["id"]=1014239,["key"]=1014239,["nextId"]={1014240}
,["talk"]="宙斯",["talkRoleID"]={7001001}
,["talk_en"]="Zeus",["showStory"]=2,["content"]="她的預言詩寫道我會被你奪走一切，可並沒有寫我會就此隕落。",["header_center"]=2}
,[1014240]={["id"]=1014240,["key"]=1014240,["nextId"]={1014241}
,["talk"]="宙斯",["header_center"]=2,["talk_en"]="Zeus",["showStory"]=2,["content"]="況且如今的我還有什麼是可以被你奪走的呢？",["talkRoleID"]={7001001}
}
