,["nextId"]={1014308}
,["talk"]="阿爾卑斯",["talkRoleID"]={1001001}
,["talk_en"]="Alps",["header_left"]=6,["content"]="總隊長，普羅米修斯，你們還好嗎？",["showStory"]=2}
