}
,["id"]=1014467,["key"]=1014467,["nextId"]={1014468}
,["talk"]="普羅米修斯",["talkRoleID"]={9906001}
,["talk_en"]="Prometheus",["showStory"]=2,["content"]="你先稍微冷靜一下。",["header_center"]=6}
