,["nextId"]={2030156}
,["talk"]="基因學家",["talkRoleID"]={9946001}
,["talk_en"]="Geneticist",["showStory"]=2,["content"]="別再轉移話題了！你敢否認你和尤尼貝克的聯繫嗎？",["header_right"]=1}
,[2030156]={["key"]=2030156,["id"]=2030156,["mask"]={1,0,1}
,["nextId"]={2030157}
,["talk"]="基因學家",["talkRoleID"]={9946001}
,["talk_en"]="Geneticist",["showStory"]=2,["content"]="無論如何，她是你的母親，這個事實絕不會有錯。",["header_right"]=1}
