,["showStory"]=2,["talk"]="女王蜂",["talkRoleID"]={5001001}
,["talk_en"]="Queenbee",["key"]=2030817,["header_left"]=7,["content"]="看來趕上了呢，下午好，總隊長和大家。",["nextId"]={2030818}
