,[1050116]={["key"]=1050116,["roleInfos"]={{["id"]=9958001,["out"]=2,["pos"]=2}
}
,["id"]=1050116,["nextId"]={1050117}
,["content"]="與議事錘敲擊聲一同響起的，還有一個帶著少許沙啞卻中氣十足的女聲。",["showStory"]=1}
