,[1050821]={["key"]=1050821,["roleInfos"]={{["id"]=6021001,["enter"]=2,["pos"]=2}
}
,["imgContent"]={"Bg_9074.jpg"}
,["imgChangeType"]=1,["nextId"]={1050822}
,["talk"]="龍弦",["talkRoleID"]={6021001}
,["talk_en"]="Longxian",["id"]=1050821,["showStory"]=2,["imgDelay"]={0.5,0.25}
,["content"]="但这个空间门的颜色……我总是感觉和之前的小型空间门有一点差别啊。"}
