}
,["id"]=1050867,["nextId"]={1050868}
,["content"]="伊德海拉倏然轉身面對牆壁，用後背對著你和塞萊斯汀。",["showStory"]=1}
,[1050868]={["roleInfos"]={{["id"]=9946001,["out"]=2,["pos"]=2}
}
,["id"]=1050868,["key"]=1050868,["nextId"]={1050869}
