,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=2,["content"]="都是一些低等級的造物……",["showIcon"]=1}
,[2170641]={["isLeader"]=1,["id"]=2170641,["key"]=2170641,["nextId"]={2170642}
,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=2,["content"]="……看起來這些低等造物已經習慣了地球的生活。",["showIcon"]=1}
