,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=2,["content"]="洛貝拉，希望流星工業能在你的帶領下，提升到新的高度。",["showIcon"]=1}
,[1054247]={["isLeader"]=1,["id"]=1054247,["key"]=1054247,["nextId"]={-1}
,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=2,["content"]="……起碼，不能比那個人差太多。",["showIcon"]=1}
,[1054301]={["imgContent"]={"Bg_9111.jpg"}
