,["id"]=1054315,["nextId"]={1054316}
,["talk"]="天叢雲",["talkRoleID"]={6006001}
,["talk_en"]="Kusanagi",["key"]=1054315,["content"]="唔……總隊長不想提就不提，我們不會多問的。",["showStory"]=2}
