,[2110062]={["key"]=2110062,["imgDelay"]={0.5,0.25}
,["imgContent"]={"Cg_2120.jpg"}
,["imgChangeType"]=1,["id"]=2110062,["nextId"]={2110063}
,["content"]="沒來得及出聲，她已經前傾身體，開始檢查你的大腿狀況。",["showStory"]=1}
