,[2110092]={["isLeader"]=1,["id"]=2110092,["key"]=2110092,["nextId"]={2110093}
,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=2,["content"]="（是單純的走散……還是說只有我一個人傳送成功？）",["showIcon"]=1}
