,{["id"]=6011001,["out"]=2,["pos"]=3}
}
,["id"]=2040227,["content"]="當卡蒂雅的手剛摸到一顆糖果時，房間陡然陷入黑暗。",["imgDelay"]={0.5,0.25}
}
,[2040228]={["talk"]="烏斯懷亞",["key"]=2040228,["talkRoleID"]={3048001}
,["talk_en"]="Ushuaia",["id"]=2040228,["nextId"]={2040229}
,["content"]="是、是敵人偷襲？",["showStory"]=2}
