}
,["id"]=1021298,["key"]=1021298,["nextId"]={1021299}
,["talk"]="佩羅",["talkRoleID"]={3032001}
,["talk_en"]="Pelorovis",["showStory"]=2,["content"]="我也是這麼想的，問題是什麼時候動手的？又有什麼企圖？",["header_center"]=5}
