,["nextId"]={2042629}
,["header_right"]=1,["talkRoleID"]={4005001}
,["talk_en"]="Vortex",["showStory"]=2,["header_left"]=5,["content"]="琶音姐？赭猩？赫爾墨斯？你們能出來一下嗎？",["talk"]="渦流"}
