,["talk_en"]="Loki",["roleInfos"]={{["id"]=7022001,["enter"]=2,["pos"]=2}
}
,["content"]="真不愧是我，第一次嘗試設計這種類型的造物就能有如此高的完成度。",["showStory"]=2}
,[1021405]={["grayEffect"]=1,["id"]=1021405,["nextId"]={1021406}
,["talk"]="洛基",["talkRoleID"]={7022001}
