,[1060706]={["id"]=1060706,["key"]=1060706,["nextId"]={1060707}
,["talk"]="洛貝拉",["header_center"]=3,["talk_en"]="Lobera",["showStory"]=2,["content"]="看來也只能攀爬上去了，就當是偶爾的鍛煉活動吧。",["talkRoleID"]={6033001}
