,["talk"]="艾蓮",["talkRoleID"]={2003010}
,["talk_en"]="Ellen",["showStory"]=2,["content"]="雖然聽不太懂……但你難道想統治世界，或者報復世界嗎？",["header_center"]=1}
,[2191301]={["id"]=2191301,["key"]=2191301,["nextId"]={2191302}
,["talk"]="希羅",["header_center"]=5,["talk_en"]="Heero",["showStory"]=2,["content"]="我希望你能少看點文娛作品，多讀點書。",["talkRoleID"]={9992001}
}
