,[1062902]={["key"]=1062902,["id"]=1062902,["nextId"]={1062903}
,["content"]="夜色依舊深濃。",["showStory"]=1}
,[2191309]={["id"]=2191309,["key"]=2191309,["nextId"]={2191310}
,["talk"]="希羅",["header_center"]=5,["talk_en"]="Heero",["showStory"]=2,["content"]="我會把安全路線發送給維拉，你們跟著她離開就行。",["talkRoleID"]={9992001}
