,["talkRoleID"]={2003010}
,["content"]="妮娜，你肚子餓了嗎？",["imgDelay"]={0.5,0.25}
}
,[1062950]={["isLeader"]=1,["id"]=1062950,["key"]=1062950,["nextId"]={1062951}
,["talk"]="%s",["showIcon"]=1,["showStory"]=2,["talkRoleID"]={100000}
,["content"]="如果是這樣的話，我們就選擇動手。",["header_center"]=3}
