,["talk"]="翼蓑",["header_center"]=2,["talk_en"]="Glaucus",["showStory"]=2,["content"]="那……所以呢？",["talkRoleID"]={3044001}
}
,[1063627]={["isLeader"]=1,["id"]=1063627,["key"]=1063627,["nextId"]={1063628}
,["talk"]="%s",["showIcon"]=1,["showStory"]=2,["talkRoleID"]={100000}
,["content"]="手會痛。",["header_center"]=2}
