,[1063654]={["isLeader"]=1,["id"]=1063654,["key"]=1063654,["nextId"]={1063655}
,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=2,["content"]="（沒有猶豫的時間了。）",["showIcon"]=1}
