,[1063958]={["roleInfos"]={{["id"]=3044001,["enter"]=2,["pos"]=2}
}
,["id"]=1063958,["key"]=1063958,["nextId"]={1063959}
,["talk"]="翼蓑",["talkRoleID"]={3044001}
,["talk_en"]="Glaucus",["showStory"]=2,["content"]="啊？薩斯塔，你該不會被她身上的金錢味道腐蝕了吧？",["header_center"]=2}
,[1063959]={["roleInfos"]={{["id"]=3015001,["enter"]=2,["pos"]=2}
}
,["id"]=1063959,["key"]=1063959,["nextId"]={1063960}
