,["talk"]="%s",["showIcon"]=1,["showStory"]=1,["talkRoleID"]={100000}
,["content"]="確實有什麼從我們頭頂飛過。",["header_center"]=4}
,[1064346]={["key"]=1064346,["header_center"]=7,["id"]=1064346,["nextId"]={1064347}
,["content"]="洛貝拉略顯煩躁地轉了轉握著的傘柄。",["showStory"]=1}
,[1023694]={["isLeader"]=1,["id"]=1023694,["key"]=1023694,["nextId"]={1023695}
