,[1064445]={["id"]=1064445,["key"]=1064445,["nextId"]={1064446}
,["talk"]="洛貝拉",["header_center"]=3,["talk_en"]="Lobera",["showStory"]=2,["content"]="如果沒有其他問題，那就準備出發吧。",["talkRoleID"]={6033001}
