,["nextId"]={1064516}
,["key"]=1064515,["imgChangeType"]=1,["showStory"]=1,["content"]="走過漫長的通道後，出現在眼前的是似曾相識的建築風格。",["imgDelay"]={0.5,0.25}
}
,[1064516]={["isLeader"]=1,["id"]=1064516,["key"]=1064516,["nextId"]={1064517}
,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=2,["content"]="（是收束塔內部的風格……出現在這裏，是證明了這個基地確實是阿卡斯非常看重的地方嗎？）",["showIcon"]=1}
,[1064517]={["key"]=1064517,["id"]=1064517,["nextId"]={1064518}
,["content"]="你抬手看了一眼手腕上的通訊器，卻意外地發現它的螢幕變成了灰白色，進入宕機狀態。",["showStory"]=1}
,[1064518]={["isLeader"]=1,["id"]=1064518,["key"]=1064518,["nextId"]={1064519}
,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=2,["content"]="你們的通訊器也宕機了嗎？",["showIcon"]=1}
,[1064519]={["roleInfos"]={{["id"]=4033001,["enter"]=2,["pos"]=2}
}
