,[2051317]={["id"]=2051317,["key"]=2051317,["nextId"]={2051318}
,["talk"]="槍棘",["header_center"]=7,["talk_en"]="Stinger",["showStory"]=2,["content"]="雖然都是利用智慧勇氣和工具和魚展開對決，但這其中可是有著天壤之別。",["talkRoleID"]={5003010}
}
