,["id"]=1070215,["key"]=1070215,["nextId"]={1070216}
,["talk"]="赫拉",["talkRoleID"]={7013001}
,["talk_en"]="Hera",["showStory"]=2,["content"]="既然是她自己的決定，我尊重她的想法。",["header_center"]=4}
,[1070216]={["id"]=1070216,["key"]=1070216,["nextId"]={1070217}
,["talk"]="赫拉",["header_center"]=5,["talk_en"]="Hera",["showStory"]=2,["content"]="但作為她曾經的同伴，我只是覺得她應該選擇更好的承繼者。",["talkRoleID"]={7013001}
}
,[1070217]={["roleInfos"]={{["id"]=9906001,["enter"]=2,["pos"]=2}
}
,["id"]=1070217,["key"]=1070217,["nextId"]={1070218}
,["talk"]="普羅米修斯",["talkRoleID"]={9906001}
,["talk_en"]="Prometheus",["showStory"]=2,["content"]="這也只是‘你覺得’而已。",["header_center"]=1}
,[1070218]={["key"]=1070218,["header_center"]=1,["roleInfos"]={{["id"]=7013001,["enter"]=2,["pos"]=2}
}
,["id"]=1070218,["nextId"]={1070219}
,["content"]="赫拉深深地看了普羅米修斯一眼，輕哼了一聲。",["showStory"]=1}
