}
,["id"]=2141550,["nextId"]={2141551}
,["talk"]="赤狼",["talkRoleID"]={3020001}
,["talk_en"]="Direwolf",["key"]=2141550,["content"]="好長，就叫做喵喵吧~",["showStory"]=2}
