}
,["id"]=1072323,["key"]=1072323,["nextId"]={1072324}
,["talk"]="洛貝拉",["talkRoleID"]={6033001}
,["talk_en"]="Lobera",["showStory"]=2,["content"]="好了，別在這裏自言自語了，這樣只會浪費時間。",["header_center"]=3}
