,["id"]=2060115,["nextId"]={2060116}
,["content"]="每停工一天，我的損失都在飛速增長！",["showStory"]=2}
,[2060116]={["isLeader"]=1,["id"]=2060116,["key"]=2060116,["nextId"]={2060117}
