}
,["id"]=2060134,["key"]=2060134,["nextId"]={2060135}
,["talk"]="幻響",["talkRoleID"]={2015001}
,["talk_en"]="Fantasia",["showStory"]=2,["content"]="總隊長！我發現這裏的——唔？！",["header_center"]=1}
,[2060135]={["key"]=2060135,["header_center"]=3,["id"]=2060135,["nextId"]={2060136}
,["content"]="一根黑糖棒棒糖準確地塞進幻響的嘴裏，把她的話堵住了。",["showStory"]=1}
