,["talk"]="幻響",["header_center"]=3,["talk_en"]="Fantasia",["showStory"]=2,["content"]="唔？！唔唔唔唔唔！（唔？G.G.G.你在幹什麼？）",["talkRoleID"]={2015001}
}
