,["talk"]="%s",["showIcon"]=1,["showStory"]=2,["talkRoleID"]={100000}
,["content"]="可以這樣說。",["header_center"]=6}
,[1030178]={["roleInfos"]={{["id"]=7033001,["enter"]=2,["pos"]=2}
}
