,["id"]=1030179,["key"]=1030179,["nextId"]={1030180}
,["talk"]="奧西裡斯",["talkRoleID"]={7032001}
,["talk_en"]="Osiris",["showStory"]=2,["content"]="阿努比斯，話題已經偏離太遠了。",["header_center"]=4}
