}
,["id"]=1030181,["key"]=1030181,["nextId"]={1030182}
,["talk"]="阿努比斯",["talkRoleID"]={7033001}
,["talk_en"]="Anubis",["showStory"]=2,["content"]="……這算是你在示弱嗎？",["header_center"]=5}
