}
,["id"]=1030182,["key"]=1030182,["nextId"]={1030183}
,["talk"]="奧西裡斯",["talkRoleID"]={7032001}
,["talk_en"]="Osiris",["showStory"]=2,["content"]="這是我的懇求。",["header_center"]=4}
