,["talk"]="奧西裡斯",["header_center"]=4,["talk_en"]="Osiris",["showStory"]=2,["content"]="她讓我代替她，向尼克羅贖罪。但我始終覺得，我虧欠阿圖姆一條性命。",["talkRoleID"]={7032001}
}
,[1030189]={["roleInfos"]={{["id"]=7033001,["enter"]=2,["pos"]=2}
}
,["id"]=1030189,["key"]=1030189,["nextId"]={1030190}
,["talk"]="阿努比斯",["talkRoleID"]={7033001}
,["talk_en"]="Anubis",["showStory"]=2,["content"]="……",["header_center"]=5}
,[1030190]={["id"]=1030190,["key"]=1030190,["nextId"]={1030191}
,["talk"]="阿努比斯",["header_center"]=5,["talk_en"]="Anubis",["showStory"]=2,["content"]="我不能理解你的想法，但尼克羅的住民們需要新的出路。",["talkRoleID"]={7033001}
}
