,["id"]=1030202,["key"]=1030202,["nextId"]={1030203}
,["talk"]="卡尼斯",["talkRoleID"]={3004001}
,["talk_en"]="Kenai",["showStory"]=2,["content"]="都沒事就好——說起來，為什麽好端端的投送艙會突然出問題啊？",["header_center"]=6}
,[1030203]={["id"]=1030203,["key"]=1030203,["nextId"]={1030204}
