,[1030441]={["id"]=1030441,["key"]=1030441,["nextId"]={1030442}
,["talk"]="普羅米修斯",["header_center"]=1,["talk_en"]="Prometheus",["showStory"]=2,["content"]="原來尼克羅把建築都遷入了地下……",["talkRoleID"]={9906001}
