,[1030908]={["isLeader"]=1,["id"]=1030908,["key"]=1030908,["nextId"]={1030909}
,["talk"]="%s",["showIcon"]=1,["showStory"]=1,["talkRoleID"]={100000}
,["content"]="為什麽合成人是碎星人的禁忌？",["header_center"]=1}
,[1030909]={["id"]=1030909,["key"]=1030909,["nextId"]={1030910}
,["talk"]="普羅米修斯",["header_center"]=1,["talk_en"]="Prometheus",["showStory"]=2,["content"]="人不是流水線上的工藝品，而是獨一無二的個體。",["talkRoleID"]={9906001}
