,["talk"]="赤狼",["talkRoleID"]={3020001}
,["talk_en"]="Direwolf",["showStory"]=2,["content"]="……",["header_center"]=5}
,[2000050]={["key"]=2000050,["header_center"]=5,["id"]=2000050,["nextId"]={2000051}
,["content"]="看來說服巴德蘭茲是不可能的任務了。她轉頭看向害她們陷入如此焦灼狀況的始作俑者。",["showStory"]=1}
,[1032801]={["key"]=1032801,["roleInfos"]={{["id"]=7031001,["enter"]=2,["pos"]=2}
}
