,[2000731]={["id"]=2000731,["key"]=2000731,["nextId"]={2000732}
,["talk"]="赤狼",["header_center"]=5,["talk_en"]="Direwolf",["showStory"]=2,["content"]="該不會你從來沒有來過擬真活動室吧！！",["talkRoleID"]={3020001}
