,["talk"]="女王蜂",["talkRoleID"]={5001001}
,["talk_en"]="Queenbee",["key"]=1000530,["content"]="別廢話啦！遊戲都進行到這裡了，難道還有返回鍵嗎？",["showStory"]=2}
,[2001045]={["key"]=2001045,["header_center"]=6,["id"]=2001045,["nextId"]={2001046}
