,[2001046]={["isLeader"]=1,["id"]=2001046,["key"]=2001046,["nextId"]={2001047}
,["talk"]="%s",["showIcon"]=1,["showStory"]=1,["talkRoleID"]={100000}
,["content"]="原來是她。",["header_center"]=6}
