,[1034808]={["id"]=1034808,["key"]=1034808,["nextId"]={1034809}
,["talk"]="阿努比斯",["header_center"]=1,["talk_en"]="Anubis",["showStory"]=2,["content"]="你們來自何處，怎麽會來到尼克羅？",["talkRoleID"]={7033001}
