,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=1,["content"]="第三分隊全體成員，準備作戰，目標——機械天使！",["showIcon"]=1}
,[2070021]={["id"]=2070021,["key"]=2070021,["nextId"]={2070022}
