,[1052519]={["id"]=1052519,["key"]=1052519,["nextId"]={1052520}
,["talk"]="龍弦",["header_center"]=1,["talk_en"]="Longxian",["showStory"]=2,["content"]="*激烈的且專門針對你的口語*。",["talkRoleID"]={6021001}
