,["talk"]="%s",["showIcon"]=1,["showStory"]=2,["talkRoleID"]={100000}
,["content"]="……阿卡斯，說出你把我引導過來的用意吧。",["header_center"]=5}
,[1062720]={["key"]=1062720,["header_center"]=5,["id"]=1062720,["nextId"]={1062721}
