,["talk"]="卡蒂雅",["talkRoleID"]={9908001}
,["talk_en"]="Katya",["key"]=2010124,["content"]="交出烏波——",["showStory"]=2}
,[2010125]={["roleInfos"]={{["id"]=9906001,["enter"]=2,["pos"]=2}
