,["id"]=2010135,["nextId"]={2010136}
,["talk"]="卡蒂雅",["talkRoleID"]={9908001}
,["talk_en"]="Katya",["key"]=2010135,["content"]="後勤部再缺人也不會讓你去的……",["showStory"]=2}
,[2010136]={["roleInfos"]={{["id"]=6009001,["enter"]=2,["pos"]=2}
}
