,[2011439]={["isLeader"]=1,["id"]=2011439,["key"]=2011439,["nextId"]={2011440}
,["talk"]="%s",["talkRoleID"]={100000}
,["showStory"]=1,["content"]="你做得很好，雖然行動太過衝動，但就結果而言值得表揚。",["showIcon"]=1}
