,["id"]=1021708,["nextId"]={1021709}
,["talk"]="普羅米修斯",["talkRoleID"]={9906001}
,["talk_en"]="Prometheus",["key"]=1021708,["content"]="眼下看來，確實如此。",["showStory"]=2}
