,["id"]=1022030,["nextId"]={1022031}
,["talk"]="蜻蛉",["talkRoleID"]={5018001}
,["talk_en"]="Odonata",["key"]=1022030,["content"]="如果不是奧丁看走了眼，那就是托爾身上真的有著能改變什麼的力量。",["showStory"]=2}
,[1022031]={["roleInfos"]={{["id"]=3032001,["enter"]=2,["pos"]=2}
