,["id"]=1022078,["nextId"]={1022079}
,["talk"]="普羅米修斯",["talkRoleID"]={9906001}
,["talk_en"]="Prometheus",["key"]=1022078,["content"]="嗯，立刻行動吧，得在世界樹發動下次攻擊前……",["showStory"]=2}
,[1022079]={["roleInfos"]={{["id"]=7026001,["enter"]=2,["pos"]=2}
