}
,[1042908]={["key"]=1042908,["header_center"]=2,["id"]=1042908,["nextId"]={1042909}
,["content"]="鳴刃接過餅乾，皺起的眉頭卻並沒有舒展，而是歎了一口氣。",["showStory"]=1}
,[1042909]={["id"]=1042909,["key"]=1042909,["nextId"]={1042910}
