,["talk"]="%s",["showIcon"]=1,["showStory"]=2,["talkRoleID"]={100000}
,["content"]="但更愚蠢的做法是，在還沒開始做這件事前，就先為可能的後果擔心。",["header_center"]=4}
,[1042915]={["id"]=1042915,["key"]=1042915,["nextId"]={1042916}
